var paths=new[]{"Assets/Prefabs/Player/Player.prefab","Assets/Prefabs/Weapons/Enemy_Entity.prefab","Assets/Prefabs/Bosses/SH10_L01_BossGameplay.prefab"};var lines=new System.Collections.Generic.List<string>();foreach(var path in paths){var root=UnityEditor.PrefabUtility.LoadPrefabContents(path);try{var health=root.GetComponent<SoulHunter.Gameplay.Combat.HealthController>();var enemy=root.GetComponent<SoulHunter.Gameplay.AI.EnemyController>();var so=health?new UnityEditor.SerializedObject(health):null;var hp=so?.FindProperty("_maxHealth");lines.Add(path+" maxHealth="+(hp!=null?hp.intValue.ToString():"runtime/data")+" enemyController="+(enemy!=null));}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}}var data=UnityEditor.AssetDatabase.FindAssets("t:EnemyData",new[]{"Assets"}).Select(g=>UnityEditor.AssetDatabase.GUIDToAssetPath(g)).Select(p=>{var d=UnityEditor.AssetDatabase.LoadAssetAtPath<SoulHunter.Gameplay.Data.EnemyData>(p);return p+" maxHealth="+d.MaxHealth+" moveSpeed="+d.MoveSpeed;});return string.Join("\n",lines.Concat(data));
